const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let index = 0;

let c = input[index++];
let d = input[index++];
let n = input[index++];
let m = input[index++];
let k = input[index++];
let commonParty = n * m;
let must = commonParty - k;

function calculateC() {
    let tempCommonParty = must;
    let sumTask = 0;

    while (tempCommonParty > 0) {
        tempCommonParty -= n;
        sumTask += c;
    }

    return sumTask;
}

function calculateD() {
    let tempCommonParty = must;
    let sumTask = 0;

    while (tempCommonParty > 0) {
        tempCommonParty -= 1;
        sumTask += d;
    }

    return sumTask;
}

function calculateFull() {
    const resultC = calculateC();
    const resultD = calculateD();

    let sumTask = resultC - n;
    const partyCMinusRound = resultC * (n - 1);

    let i = must - partyCMinusRound;
    while (i > 0) {
        i -= 1;
        sumTask += d;
    }

    return Math.min(resultC, resultD, sumTask);
}

if (must > 0) {
    const resultC = calculateC();
    const resultD = calculateD();

    let resultJoint = resultC - c;
    const partyCMinusRound = Math.trunc(resultJoint / c) * n;

    let i = must - partyCMinusRound;
    while (i > 0) {
        i -= 1;
        resultJoint += d;
    }

    console.log(Math.min(resultC, resultD, resultJoint));
} else {
    console.log(0);
}

